import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

export const BASELINE_NAME = "20260924000000_baseline.sql";

export function schemaFiles(root: string): string[] {
  const dir = join(root, "supabase", "schemas");
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((name) => name.endsWith(".sql"))
    .sort()
    .map((name) => join(dir, name));
}

export function buildBaseline(root: string): string {
  const header =
    "-- Generated by `bogey db baseline` from supabase/schemas. Do not edit; edit the schema files.\n";
  return (
    header +
    schemaFiles(root)
      .map((path) => {
        const rel = path.slice(root.length + 1);
        return `\n-- ─── ${rel} ${"─".repeat(Math.max(0, 70 - rel.length))}\n\n${readFileSync(path, "utf-8").trim()}\n`;
      })
      .join("")
  );
}
